"""Starting the MT5 terminal in Docker, so a node can bring its own venue.

The same shape as `nautilus_trader.adapters.interactive_brokers.gateway`:
`DockerizedIBGateway` manages a TWS container and hands the factory a port,
and `DockerizedMT5Terminal` manages a `ghcr.io/nodalytics/mt5-terminal`
container and hands the factory a `base_url`. A config field on either client
turns it on; absent, nothing here runs and the clients talk to whatever
`base_url` says, which is the lab box.

    exec_clients={MT5: MT5ExecClientConfig(
        dockerized_terminal=DockerizedMT5TerminalConfig(
            login=12345678, password=..., server="Deriv-Demo",
        ),
    )}

What is in the container: MT5 under Wine, a FastAPI bridge on `MT5_API_PORT`,
and a VNC web interface on 6901 for the one thing no API can do - clicking
through the terminal's own dialogs when a broker changes something.

## Readiness is the terminal's answer, not the container's

`GET /health` returns `{"status", "version", "connected", "trade_allowed",
"build"}` and needs no API key, and **the image's own README warns that
`status` reflects only the web service**. So a container whose HTTP is up and
whose terminal has not logged in answers `status: ok` with `connected: false`.
This waits on `connected`, and reports `trade_allowed` without waiting on it -
a terminal that is connected but has trading disabled is a real state, usually
a broker's weekend, and refusing to start then would make a Sunday deploy
impossible.

That distinction is not pedantry here. Three deploys on 2026-10-09 were built,
tagged, health-checked and reported up while running none of the code they
claimed, because every check read our own side of the wire. A container that is
`running` is our side. `connected: true` is the venue's.

## Pin the build

`MT5_SETUP_URL` chooses which terminal installer the image fetches, and an
unpinned one has already broken this desk: an unpinned `mt5setup` against a
pinned `MetaTrader5==5.0.5640` produced a terminal whose IPC the Python module
could not speak - **build 6140 works, 6204 does not**. `setup_url` is
therefore a field rather than something left to the image's default, and
`version()` reads the build back out of `/health` so a deploy can record which
one it actually got.
"""

from __future__ import annotations

import time
from enum import IntEnum
from typing import Any, ClassVar

import httpx

#: The published image. `latest` is deliberate for the *image* and deliberate
#: in the other direction for the terminal inside it - see `setup_url`: the
#: bridge is ours and moves forward, the terminal build is pinned because an
#: unpinned one has broken IPC before.
IMAGE = "ghcr.io/nodalytics/mt5-terminal:latest"

#: What the image serves inside the container.
API_PORT = 8000
VNC_PORT = 6901


def container_name(config: Any, base: str = "till-mt5-terminal") -> str:
    """Named after the account, not just the image.

    Two terminals are two accounts - a demo and a live one is the usual pair -
    and a shared container name would mean the second node silently reused the
    first's account. `judge-the-desk-on-the-broker-not-the-journal` is the
    same failure a level down: the desk believed its own label rather than the
    venue's.

    A module function rather than a method so it can be checked without a
    Docker daemon, which is also why `environment` is one.
    """
    login = int(getattr(config, "login", 0) or 0)
    return f"{base}-{login}" if login else base


def environment(config: Any) -> dict[str, str]:
    """The image's variables, as its README names them.

    `extra` last so a deployment can set anything this does not model - the
    image has more knobs than a config should enumerate, and a field per knob
    here is a field to keep in step with someone else's repo.

    **`MT5_API_PORT` is the port inside the container and is not the config's
    `port`**, which is where it lands on this host. Setting the inside one
    from the outside one is the mistake that publishes 8000 to a terminal
    listening on something else, and the symptom is a container that runs and
    a bridge that never answers.
    """
    env: dict[str, str] = {"MT5_API_PORT": str(API_PORT)}
    if getattr(config, "login", 0):
        env["MT5_LOGIN"] = str(int(config.login))
    if getattr(config, "password", None):
        env["MT5_PASSWORD"] = str(config.password)
    if getattr(config, "server", None):
        env["MT5_SERVER"] = str(config.server)
    if getattr(config, "api_key_seed", None):
        env["API_KEY_SEED"] = str(config.api_key_seed)
    if getattr(config, "setup_url", None):
        env["MT5_SETUP_URL"] = str(config.setup_url)
    if getattr(config, "vnc_user", None):
        env["VNC_USER"] = str(config.vnc_user)
    if getattr(config, "vnc_password", None):
        env["VNC_PASSWORD"] = str(config.vnc_password)
    env.update({str(k): str(v) for k, v in (getattr(config, "extra", None) or {}).items()})
    return env


class Status(IntEnum):
    """Where a container is, in the order it gets there."""

    NONE = 1
    CREATED = 2
    STARTING = 3
    STOPPED = 4
    NOT_CONNECTED = 5
    READY = 6
    UNKNOWN = 7


class DockerizedMT5Terminal:
    """One MT5 terminal in one container, started and waited for."""

    CONTAINER: ClassVar[str] = "till-mt5-terminal"

    def __init__(self, config: Any) -> None:
        from nautilus_trader.common.component import Logger

        self.log = Logger(type(self).__name__)
        self._cfg = config
        self.host = config.host or "127.0.0.1"
        self.port = int(config.port or API_PORT)
        self.vnc_port = config.vnc_port
        self.timeout = int(config.timeout or 300)
        try:
            import docker
        except ImportError as exc:
            raise RuntimeError(
                "docker is required for a dockerized terminal: `uv sync --extra docker`"
            ) from exc
        self._docker_module = docker
        # `use_context=False` for the same reason the IB adapter passes it: a
        # developer's docker context can point at a remote daemon, and a
        # terminal started on the wrong host is a terminal nothing can reach.
        self._client = docker.from_env(use_context=False)
        self._container: Any = None

    def __repr__(self) -> str:
        return f"{type(self).__name__}({self.base_url})"

    @property
    def base_url(self) -> str:
        """What a client config should point at once this is up."""
        return f"http://{self.host}:{self.port}"

    @property
    def container_name(self) -> str:
        return container_name(self._cfg, self.CONTAINER)

    @property
    def container(self) -> Any:
        if self._container is None:
            found = {c.name: c for c in self._client.containers.list(all=True)}
            self._container = found.get(self.container_name)
        return self._container

    @property
    def status(self) -> Status:
        container = self.container
        if container is None:
            return Status.NONE
        state = getattr(container, "status", "")
        if state == "running":
            health = self.health()
            if not health:
                return Status.STARTING
            if health.get("connected"):
                return Status.READY
            return Status.NOT_CONNECTED
        if state in ("created",):
            return Status.CREATED
        if state in ("stopped", "exited", "dead"):
            return Status.STOPPED
        return Status.UNKNOWN

    def health(self) -> dict[str, Any]:
        """`GET /health`, or `{}` if it did not answer.

        Needs no API key by design, which is what makes it usable as a
        readiness probe: the key is derived from `API_KEY_SEED` inside the
        container, so a caller waiting for the terminal does not have one yet.
        """
        try:
            response = httpx.get(f"{self.base_url}/health", timeout=5.0)
        except Exception:
            return {}
        if response.status_code >= 400:
            return {}
        try:
            body = response.json()
        except ValueError:
            return {}
        return body if isinstance(body, dict) else {}

    def version(self) -> int:
        """The terminal build the image actually installed.

        Worth recording on every start: an unpinned installer is how this desk
        got a terminal whose IPC `MetaTrader5` could not speak, and the build
        number is the only thing that distinguishes 6140 from 6204 after the
        fact.
        """
        return int(self.health().get("build") or 0)

    def start(self, wait: int | None = None) -> None:
        """Ensure a ready terminal, reusing one where that is safe."""
        status = self.status
        if status in (Status.READY, Status.STARTING, Status.NOT_CONNECTED):
            # Reused rather than replaced. A running terminal holds a logged-in
            # session, and restarting it to be tidy costs a login and whatever
            # the broker does about two sessions on one account.
            self.log.info(f"{self.container_name}: {status.name}, using the running container")
            if status is not Status.READY:
                self._await(wait)
            return
        if status in (Status.STOPPED, Status.CREATED, Status.UNKNOWN):
            self.log.warning(f"{self.container_name}: {status.name}, removing it")
            self.stop()

        ports: dict[str, Any] = {str(API_PORT): (self.host, self.port)}
        if self.vnc_port is not None:
            ports[str(VNC_PORT)] = (self.host, int(self.vnc_port))

        self.log.info(f"{self.container_name}: starting {self._cfg.image}")
        self._container = self._client.containers.run(
            image=self._cfg.image,
            name=self.container_name,
            detach=True,
            # `unless-stopped`, not `always`: a node that is brought down
            # deliberately should not have its venue come back on the next
            # boot of the host and start answering for an account nothing is
            # watching.
            restart_policy={"Name": "unless-stopped"},
            ports=ports,
            environment=environment(self._cfg),
        )
        self._await(wait)

    def _await(self, wait: int | None = None) -> None:
        """Wait for `connected`, and say what the terminal is when it arrives."""
        limit = int(wait or self.timeout)
        for _ in range(limit):
            health = self.health()
            if health.get("connected"):
                # `trade_allowed` is reported and not required: a connected
                # terminal with trading closed is a weekend, not a failure.
                self.log.info(
                    f"{self.container_name}: connected, build {health.get('build')}, "
                    f"trade_allowed={health.get('trade_allowed')}"
                )
                return
            time.sleep(1)
        raise RuntimeError(
            f"{self.container_name} did not report connected within {limit}s. "
            f"`/health` last said {self.health() or 'nothing'} - a container that is "
            f"running is our side of the wire, and `connected` is the venue's."
        )

    def safe_start(self, wait: int | None = None) -> None:
        try:
            self.start(wait=wait)
        except self._docker_module.errors.APIError as exc:
            raise RuntimeError(f"could not start {self.container_name}: {exc}") from exc

    def stop(self) -> None:
        container = self.container
        if container is None:
            return
        try:
            container.stop()
            container.remove()
        finally:
            self._container = None

    def __enter__(self) -> DockerizedMT5Terminal:
        self.start()
        return self

    def __exit__(self, *exc: object) -> None:
        self.stop()


__all__ = [
    "API_PORT",
    "IMAGE",
    "VNC_PORT",
    "DockerizedMT5Terminal",
    "Status",
    "container_name",
    "environment",
]
